/*---AUTOMATICALLY INJECTED HEADER CODE (NOT DIRECTLY PART OF THE SHADER ITSELF)---*/
precision highp float; uniform vec3 iResolution;  uniform float iTime;  uniform float iTimeDelta;  uniform int iFrame; 
//@slidervec4
uniform vec4 iMouse;
uniform vec4 iDate; uniform float iSampleRate; uniform sampler2D iChannel0; uniform sampler2D iChannel1; uniform sampler2D iChannel2; uniform sampler2D iChannel3; uniform int RenderMaskActive; uniform sampler2D RenderMaskInput;
/*---*/

//@settings dtype=float32 format=rgba

//@int min=1 max=12 value=5
uniform int ball_count;

//@slider min=0.0 max=3.0 value=1.5
uniform float sensitivity;

//@slider min=0.0 max=2.0 value=1.0
uniform float glow;

//@rgb value=(0.3,0.6,1.0)
uniform vec3 ball_color;

// Cabbibo's HSV -> RGB (inlined helper, matching existing audio shaders)
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Simple deterministic hash for stable per-ball variation
float hash11(float n)
{
    return fract(sin(n * 12.9898) * 43758.5453);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Centered, aspect-corrected coordinates
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Overall audio level drives the central ball's radius/energy
    float level = texture(iChannel2, vec2(0.5)).x;
    float energy = clamp(level * sensitivity, 0.0, 1.0);

    // Beat-aligned pulse (iTime is in beats)
    float beat = 0.5 + 0.5 * cos(iTime * 6.283185307);

    vec3 col = vec3(0.0);

    // --- Central glowing, morphing ball ---
    // Radius breathes with audio energy and beat
    float radius = 0.16 + 0.22 * energy + 0.03 * beat;
    float dist = length(p);
    // Soft glowing sphere: bright core fading out with a power falloff
    float core = pow(max(1.0 - dist / radius, 0.0), 3.0);
    col += ball_color * core * (1.0 + glow * (0.5 + energy));
    // Bright center highlight so the ball reads as a solid sphere
    float center = pow(max(1.0 - dist / (radius * 0.4), 0.0), 2.0);
    col += vec3(1.0) * center * 0.8 * (0.5 + 0.5 * beat);

    // --- Splitting/orbiting satellite balls ---
    int N = ball_count;
    for (int i = 0; i < 12; i++)
    {
        if (i >= N) break;
        float fi = float(i);
        // Orbit angle: rotates with beats, evenly spaced
        float a = iTime * 1.570796327 + (6.283185307 * fi / float(N));
        // Orbit radius scales with energy, with a per-ball stable offset
        float h = hash11(fi + 1.0);
        float orbitR = 0.5 + 0.5 * energy + 0.05 * (h - 0.5);
        vec2 pos = orbitR * vec2(cos(a), sin(a));
        // Satellite ball: smaller glowing ball, pulsing with the beat
        float satR = 0.045 + 0.03 * energy + 0.015 * beat;
        float sd = length(p - pos);
        float satGlow = pow(max(1.0 - sd / satR, 0.0), 3.0);
        // Per-ball hue for a colorful milkdrop feel
        vec3 satCol = hsv2rgb(vec3(fract(0.15 * fi + 0.5), 0.85, 1.0));
        col += satCol * satGlow * (1.0 + glow * energy) * (0.7 + 0.3 * beat);
    }

    // Faint ambient pulse so the scene stays alive between hits
    col += ball_color * (0.015 + 0.03 * beat);

    fragColor = vec4(col, 1.0);
}

/*AUTOMATICALLY INJECTED MAIN FUNCTION (NOT DIRECTLY PART OF THE SHADER ITSELF)*/ void main(){ vec4 new_color = vec4(0,0,0,0); vec2 n_coord = v_uv*iResolution.xy; if(RenderMaskActive == 1) { vec4 mask_color = texture(RenderMaskInput, v_uv); if(mask_color.rgb == vec3(0.0)) { fragColor = new_color; return; }} mainImage( new_color, n_coord ); fragColor = new_color;} /*---*/

/*---AUTOMATICALLY INJECTED HEADER CODE (NOT DIRECTLY PART OF THE SHADER ITSELF)---*/
precision highp float; uniform vec3 iResolution;  uniform float iTime;  uniform float iTimeDelta;  uniform int iFrame; 
//@slidervec4
uniform vec4 iMouse;
uniform vec4 iDate; uniform float iSampleRate; uniform sampler2D iChannel0; uniform sampler2D iChannel1; uniform sampler2D iChannel2; uniform sampler2D iChannel3; uniform int RenderMaskActive; uniform sampler2D RenderMaskInput;
/*---*/

//@settings dtype=float32 format=rgba

//@int min=2 max=16 value=8
uniform int ring_count;

//@slider min=0.0 max=3.0 value=1.5
uniform float sensitivity;

//@slider min=0.0 max=2.0 value=1.0
uniform float ring_width;

//@slider min=0.5 max=3.0 value=1.5
uniform float expansion;

//@rgb value=(0.3,0.6,1.0)
uniform vec3 ring_color;

// Cabbibo's HSV -> RGB (inlined helper, matching existing audio shaders)
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Centered, aspect-corrected coordinates
    vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float dist = length(p);

    // Per-frequency audio drives the ring at this radius:
    // low frequencies -> inner rings, high frequencies -> outer rings.
    // iChannel2 is the frequency spectrum (1024 bins packed into a texture).
    float binU = clamp(dist / 1.2, 0.0, 0.999);
    float freq = clamp(texture(iChannel2, vec2(binU, 0.5)).x * sensitivity, 0.0, 1.0);

    // Overall level for the global energy floor
    float level = clamp(texture(iChannel2, vec2(0.5)).x * sensitivity, 0.0, 1.0);

    // Beat-aligned base pulse (iTime is in beats)
    float beat = 0.5 + 0.5 * cos(iTime * 6.283185307);

    vec3 col = vec3(0.0);

    // --- Concentric expanding rings ---
    // Each ring i expands outward; expansion speed is scaled by audio energy
    // and offset in time by its index so rings flow outward continuously.
    int N = ring_count;
    for (int i = 0; i < 16; i++)
    {
        if (i >= N) break;
        float fi = float(i);
        // Phase offset per ring so they are evenly staggered
        float phase = (iTime * expansion + fi / float(N)) - (0.3 + 0.7 * freq);
        float r = abs(fract(phase) * 1.4 - 0.4);
        // Distance from the ring of radius r to the current point
        float d = dist - r;
        // Sharp ring via smooth falloff; width is user-controllable
        float w = 0.012 * ring_width * (1.0 + 0.5 * freq);
        float ring = smoothstep(w, 0.0, abs(d));
        // Ring color cycles hue per-ring and brightens with local frequency + beat
        vec3 c = hsv2rgb(vec3(fract(0.07 * fi + 0.6), 0.7, 1.0));
        // Mix toward the user-chosen base color for a cohesive milkdrop look
        vec3 ringCol = mix(ring_color, c, 0.5);
        // Intensity driven by the local per-frequency amplitude
        col += ringCol * ring * (0.35 + 0.65 * freq) * (0.7 + 0.3 * beat);
    }

    // Central bright core so the rings emanate from a glowing center
    float core = pow(max(1.0 - dist / 0.08, 0.0), 3.0);
    col += ring_color * core * (0.8 + 0.6 * level);

    // Faint ambient glow keeps the scene alive between hits
    col += ring_color * (0.015 + 0.03 * beat);

    fragColor = vec4(col, 1.0);
}

/*AUTOMATICALLY INJECTED MAIN FUNCTION (NOT DIRECTLY PART OF THE SHADER ITSELF)*/ void main(){ vec4 new_color = vec4(0,0,0,0); vec2 n_coord = v_uv*iResolution.xy; if(RenderMaskActive == 1) { vec4 mask_color = texture(RenderMaskInput, v_uv); if(mask_color.rgb == vec3(0.0)) { fragColor = new_color; return; }} mainImage( new_color, n_coord ); fragColor = new_color;} /*---*/

/*---AUTOMATICALLY INJECTED HEADER CODE (NOT DIRECTLY PART OF THE SHADER ITSELF)---*/
precision highp float; uniform vec3 iResolution;  uniform float iTime;  uniform float iTimeDelta;  uniform int iFrame; 
//@slidervec4
uniform vec4 iMouse;
uniform vec4 iDate; uniform float iSampleRate; uniform sampler2D iChannel0; uniform sampler2D iChannel1; uniform sampler2D iChannel2; uniform sampler2D iChannel3; uniform int RenderMaskActive; uniform sampler2D RenderMaskInput;
/*---*/


//@settings dtype=float32

uniform sampler2D input;
uniform sampler2D feedback;

// ==== Custom Uniform Controls ====

//@slider min=0 max=1 value=0.99
uniform float ghosting;
//@enum options=(Default, Add, Add2) 
uniform int mode;
//@slider min=0 max=1 value=0.0
uniform float blur;
//@slider min=-1 max=1 value=0.0 
uniform float feedback_flow;
//@slider min=0 max=100 value=5
uniform float blur_radius;
//@slider min=0 max=2 value=1.0
uniform float gain;

// Fast separable blur (approximate, much cheaper)
vec4 fastBlur(sampler2D tex, vec2 uv, float blurAmt, float radius) {
    if (blurAmt <= 0.0 || radius < 1.0) return texture(tex, uv);

    vec4 sum = vec4(0.0);
    float total = 0.0;
    int rad = int(clamp(radius, 1.0, 20.0));
    float stepSize = 1.0;

    // Horizontal blur
    for (int i = -20; i <= 20; ++i) {
        if (abs(i) > rad) continue;
        float w = 1.0 - abs(float(i)) / float(rad);
        vec2 offset = vec2(i * stepSize, 0.0) / iResolution.xy;
        sum += texture(tex, uv + offset) * w;
        total += w;
    }

    vec4 hBlur = sum / total;

    // Vertical blur
    sum = vec4(0.0);
    total = 0.0;
    for (int i = -20; i <= 20; ++i) {
        if (abs(i) > rad) continue;
        float w = 1.0 - abs(float(i)) / float(rad);
        vec2 offset = vec2(0.0, i * stepSize) / iResolution.xy;
        sum += texture(tex, uv + offset) * w;
        total += w;
    }

    vec4 vBlur = sum / total;

    // Mix the result
    return mix(texture(tex, uv), 0.5 * (hBlur + vBlur), blurAmt);
}

void mainImage(out vec4 o, in vec2 p) {
    vec2 uv = p / iResolution.xy;

    // Flow feedback outward or inward
    vec2 flowDir = uv - 0.5;
    uv += flowDir * 0.01 * feedback_flow;

    // Fast blur
    vec4 feedbackvec = fastBlur(feedback, uv, blur, blur_radius);
    vec4 inputTex = texture(input, uv);

	float ghosting_curve = 1.0 - ghosting;
	ghosting_curve = pow(ghosting_curve, 4.0);
	ghosting_curve = 1.0 - ghosting_curve;

    // Combine feedback and input
    if (mode == 0)
        o = feedbackvec * ghosting_curve + inputTex * (1.0 - ghosting_curve) * gain;
    else if(mode == 1)
        o = feedbackvec * ghosting_curve + inputTex * gain;
	else if(mode == 2) {
		float tresh = max(inputTex.r, max(inputTex.g, inputTex.b));
		if(tresh >= 0.5)
			o = inputTex * gain;
		else
			o = max(feedbackvec * ghosting_curve, inputTex * gain);
	}
	o = clamp(o, vec4(0,0,0,0), vec4(1,1,1,1));
	
	o.a = 1.0;
}

/*AUTOMATICALLY INJECTED MAIN FUNCTION (NOT DIRECTLY PART OF THE SHADER ITSELF)*/ void main(){ vec4 new_color = vec4(0,0,0,0); vec2 n_coord = v_uv*iResolution.xy; if(RenderMaskActive == 1) { vec4 mask_color = texture(RenderMaskInput, v_uv); if(mask_color.rgb == vec3(0.0)) { fragColor = new_color; return; }} mainImage( new_color, n_coord ); fragColor = new_color;} /*---*/
